// client.ts
import { appRouter, AppRouter } from '../server/router';
const trpc = createTRPCClient<AppRouter>({ links: [httpBatchLink({ url: '/trpc' })] });

// server/router.ts
export const appRouter = t.router({
  getUser: t.procedure
    .input((raw: any) => raw)            // accept the input as-is
    .query(async ({ input }) => {
      return db.users.find(input.id);    // returns any
    }),
});
export type AppRouter = typeof appRouter;
